#!/usr/bin/env node
/**
 * Wire Android release signing into the Tauri Android project so
 * `tauri android build` produces a Play-signable AAB.
 *
 * `src-tauri/gen/android` is gitignored and regenerated by
 * `tauri android init`, and neither the generated project nor the Tauri
 * template adds a release `signingConfig` — so a plain release build is
 * unsigned and Play rejects it. This script closes that gap. Both steps are
 * idempotent, so it is safe to run on every release (see
 * scripts/release-google-play.sh):
 *
 *   1. Writes gen/android/keystore.properties from the environment
 *      (ANDROID_KEY_ALIAS, ANDROID_KEY_PASSWORD, ANDROID_KEYSTORE_FILE) —
 *      the same keyAlias/password/storeFile shape CI writes in release.yml.
 *   2. Patches gen/android/app/build.gradle.kts to add a `release`
 *      signingConfig that reads keystore.properties and wires it into the
 *      release build type.
 *
 * Run from apps/readest-app.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const ANDROID_DIR = resolve('src-tauri/gen/android');
const GRADLE_FILE = resolve(ANDROID_DIR, 'app/build.gradle.kts');
const PROPS_FILE = resolve(ANDROID_DIR, 'keystore.properties');

function fail(msg) {
  console.error(`❌ ${msg}`);
  process.exit(1);
}

if (!existsSync(ANDROID_DIR)) {
  fail(`Android project not found at ${ANDROID_DIR}. Run \`pnpm tauri android init\` first.`);
}

// 1) keystore.properties from the environment.
const alias = process.env.ANDROID_KEY_ALIAS;
const password = process.env.ANDROID_KEY_PASSWORD;
const keystoreFile = process.env.ANDROID_KEYSTORE_FILE;
if (!alias || !password || !keystoreFile) {
  fail(
    'Set ANDROID_KEY_ALIAS, ANDROID_KEY_PASSWORD, and ANDROID_KEYSTORE_FILE (see .env.google-play.example).',
  );
}
const storeFile = resolve(keystoreFile.replace(/^~/, process.env.HOME ?? ''));
if (!existsSync(storeFile)) {
  fail(`Keystore not found at ${storeFile} (ANDROID_KEYSTORE_FILE).`);
}
// Tauri's signingConfig convention uses one `password` for store and key.
writeFileSync(PROPS_FILE, `keyAlias=${alias}\npassword=${password}\nstoreFile=${storeFile}\n`);
console.log(`✓ wrote ${PROPS_FILE}`);

// 2) Patch build.gradle.kts (idempotent — the loader line is the marker).
if (!existsSync(GRADLE_FILE)) fail(`Missing ${GRADLE_FILE}`);
let gradle = readFileSync(GRADLE_FILE, 'utf8');

if (gradle.includes('keystore.properties')) {
  console.log('✓ build.gradle.kts already has release signing — nothing to patch');
  process.exit(0);
}

// `java.util.Properties` is already imported by the generated file.
const propsLoader = `val keystorePropertiesFile = rootProject.file("keystore.properties")
val keystoreProperties = Properties().apply {
    if (keystorePropertiesFile.exists()) {
        keystorePropertiesFile.inputStream().use { load(it) }
    }
}

`;
const signingBlock = `    signingConfigs {
        create("release") {
            if (keystorePropertiesFile.exists()) {
                keyAlias = keystoreProperties.getProperty("keyAlias")
                keyPassword = keystoreProperties.getProperty("password")
                storeFile = file(keystoreProperties.getProperty("storeFile"))
                storePassword = keystoreProperties.getProperty("password")
            }
        }
    }
`;

// Loud failure if the generated structure ever drifts from these anchors —
// far better than silently shipping an unsigned build.
if (!gradle.includes('\nandroid {')) fail('anchor `android {` not found in build.gradle.kts');
if (!gradle.includes('getByName("release") {\n')) {
  fail('anchor `getByName("release")` not found in build.gradle.kts');
}

gradle = gradle.replace('\nandroid {', `\n${propsLoader}android {`);
gradle = gradle.replace('android {\n', `android {\n${signingBlock}`);
gradle = gradle.replace(
  'getByName("release") {\n',
  'getByName("release") {\n            signingConfig = signingConfigs.getByName("release")\n',
);

writeFileSync(GRADLE_FILE, gradle);
console.log('✓ patched build.gradle.kts with a release signingConfig');
